<script setup>import {router,useForm} from '@inertiajs/vue3'; import AppLayout from '../../../Layouts/AppLayout.vue'; const props=defineProps({entry:Object,endpoints:Object}); const reverse=useForm({reason:''}); const post=()=>router.post(props.endpoints.post);</script>
<template><AppLayout :title="entry.number" eyebrow="Asiento contable" :description="`${entry.date} · ${entry.status}`"><template #header-actions><button v-if="entry.status==='draft'" class="btn-primary" @click="post">Contabilizar</button></template><section class="grid gap-3 sm:grid-cols-2"><div class="live-metric" data-tone="blue"><p>Total debe</p><strong>C$ {{entry.total_debit}}</strong></div><div class="live-metric" data-tone="emerald"><p>Total haber</p><strong>C$ {{entry.total_credit}}</strong></div></section><section class="card mt-4 overflow-hidden"><div class="section-heading"><h2 class="font-semibold">{{entry.concept}}</h2><p class="text-xs text-slate-400">{{entry.reference}}</p></div><div class="table-wrap"><table class="w-full"><thead><tr><th class="table-cell">Cuenta</th><th class="table-cell">Detalle</th><th class="table-cell text-right">Debe</th><th class="table-cell text-right">Haber</th></tr></thead><tbody><tr v-for="line in entry.lines" :key="line.id"><td class="table-cell">{{line.account.code}} · {{line.account.name}}</td><td class="table-cell">{{line.detail}}</td><td class="table-cell text-right">{{line.debit}}</td><td class="table-cell text-right">{{line.credit}}</td></tr></tbody></table></div></section><form v-if="entry.status==='posted'&&!entry.reversal" class="card mt-4 max-w-xl p-5" @submit.prevent="reverse.post(endpoints.reverse)"><h2 class="font-semibold">Registrar reversión</h2><label class="field-label mt-3 block">Motivo<textarea v-model="reverse.reason" class="control" required></textarea></label><button class="btn-danger mt-3">Reversar con asiento compensatorio</button></form></AppLayout></template>
